"""Generate the C++ / AS3 contract. Run --check to detect stale generated files.
After changing AS3, rebuild the HUD delta as documented in README.txt.
"""
from pathlib import Path
import json,re,sys
root=Path(__file__).resolve().parent.parent / "ui"
schema=json.loads((root/'contract.json').read_text())
commands=schema['commands'];arguments=schema['arguments'];sliders=schema['sliders']
assert list(commands.values())==list(range(1,47))
assert len(arguments)==24 and len(sliders)==12
header=['// Generated by tools/generate_contract.py; edit ui/contract.json instead.','#pragma once','namespace UiContract {','enum Command {']
header += [f'    {name} = {value},' for name,value in commands.items()]
header += ['};','enum Argument {']+[f'    Arg_{a.split(":")[0]} = {i},' for i,a in enumerate(arguments)]+['    ArgumentCount','};','constexpr int CommandMask=63, AssetShift=6, AssetMask=511, ValueShift=15, ValueSteps=1000;','constexpr int MaxPackedValue=(ValueSteps<<ValueShift)|(AssetMask<<AssetShift)|CommandMask;','struct Slider { float low, high; bool logarithmic; };','constexpr Slider Sliders[] = {']
def f(v):return repr(float(v))
header += [f'    {{{f(s["low"])}f, {f(s["high"])}f, {str(s["logarithmic"]).lower()}}},' for s in sliders]+['};','}']
panel=root/'PhotoPanel.as.inc';text=panel.read_text()
constants='\n'.join(f'      private static const PM_{name}:int = {v};' for name,v in commands.items())
constants+='\n      private static const PM_AssetScale:int = 64;\n      private static const PM_ValueScale:int = 32768;\n      private static const PM_ValueSteps:int = 1000;'
text=re.sub(r'(?<=// BEGIN GENERATED CONTRACT\n).*?(?=      // END GENERATED CONTRACT)',constants+'\n',text,flags=re.S)
lines='\n'.join(f'         _PM_Slider(PM_{s["command"]},{s["y"]},{s["page"]},{f(s["low"])},{f(s["high"])},{str(s["logarithmic"]).lower()});' for s in sliders)
text=re.sub(r'(?<=// BEGIN GENERATED SLIDERS\n).*?(?=         // END GENERATED SLIDERS)',lines+'\n',text,flags=re.S)
text=re.sub(r'function _PM_Update\(.*?\):Number','function _PM_Update('+', '.join(arguments)+'):Number',text)
text=text.replace('* 1000)', '* PM_ValueSteps)').replace('_pmAssets * 64 + sliderValue * 32768','_pmAssets * PM_AssetScale + sliderValue * PM_ValueScale')
outputs={root.parent/'src/generated/ui_contract.h':'\n'.join(header)+'\n',panel:text}
for path,data in outputs.items():
 if '--check' in sys.argv:
  if not path.exists() or path.read_text()!=data:raise SystemExit('Stale generated contract: '+str(path))
 else:path.write_text(data)
print('UI contract checked' if '--check' in sys.argv else 'UI contract generated')
